package cn.workbench;
import org.apache.ibatis.annotations.*;import java.util.*;
@Mapper public interface Store {
 @InsertProvider(type=ProjectionSql.class,method="insert") int insertProjection(@Param("table")String table,@Param("values")Map<String,Object> values);
 @UpdateProvider(type=ProjectionSql.class,method="update") int updateProjection(@Param("table")String table,@Param("values")Map<String,Object> values);
 @SelectProvider(type=ProjectionSql.class,method="select") Map<String,Object> projection(@Param("table")String table,@Param("id")long id);
 @Insert("INSERT INTO sub_task_assignee(sub_task_id,user_id) VALUES(#{sub},#{user})") int assign(@Param("sub")long sub,@Param("user")long user);
 @Delete("DELETE FROM sub_task_assignee WHERE sub_task_id=#{sub}") int clearAssignees(long sub);
 @Select("SELECT user_id FROM sub_task_assignee WHERE sub_task_id=#{sub}") List<Long> assignees(long sub);
 @Insert("INSERT INTO daily_task_sequence(company_id,business_date,next_value) VALUES(#{company},#{date},0) ON DUPLICATE KEY UPDATE next_value=next_value") int ensureSequence(@Param("company")int company,@Param("date")java.time.LocalDate date);
 @Select("SELECT next_value FROM daily_task_sequence WHERE company_id=#{company} AND business_date=#{date} FOR UPDATE") long sequence(@Param("company")int company,@Param("date")java.time.LocalDate date);
 @Update("UPDATE daily_task_sequence SET next_value=next_value+1 WHERE company_id=#{company} AND business_date=#{date}") int advanceSequence(@Param("company")int company,@Param("date")java.time.LocalDate date);
 @Select("SELECT * FROM app_user WHERE account=#{account}") Map<String,Object> userByAccount(String account);
 @Select("SELECT * FROM app_user WHERE id=#{id}") Map<String,Object> user(long id);
 @Select("SELECT * FROM app_user ORDER BY id") List<Map<String,Object>> users();
 String EFFECTIVE_SCOPE = "s.enabled=TRUE AND s.employment_status='ACTIVE' AND (s.valid_from IS NULL OR s.valid_from<=CURRENT_TIMESTAMP) AND (s.valid_until IS NULL OR s.valid_until>CURRENT_TIMESTAMP) AND EXISTS(SELECT 1 FROM app_user u WHERE u.id=s.user_id AND u.enabled=TRUE) AND (s.company_id IS NULL OR EXISTS(SELECT 1 FROM company c WHERE c.id=s.company_id AND c.enabled=TRUE)) AND (s.dept_id IS NULL OR EXISTS(SELECT 1 FROM department d WHERE d.id=s.dept_id AND d.company_id=s.company_id AND d.enabled=TRUE))";
 @Select("SELECT * FROM user_scope WHERE user_id=#{uid} ORDER BY id") List<Map<String,Object>> rawScopes(long uid);
 @Select("SELECT s.* FROM user_scope s WHERE s.user_id=#{uid} AND "+EFFECTIVE_SCOPE+" ORDER BY s.id") List<Map<String,Object>> scopes(long uid);
 @Select("SELECT s.* FROM user_scope s WHERE s.id=#{id} AND s.user_id=#{uid} AND "+EFFECTIVE_SCOPE) Map<String,Object> scope(@Param("uid")long uid,@Param("id")long id);
 @Insert("INSERT INTO app_user(account,name,password_hash,must_change_password) VALUES(#{account},#{name},#{passwordHash},#{mustChangePassword})") @Options(useGeneratedKeys=true,keyProperty="id") int insertUser(Map<String,Object> u);
 @Insert("INSERT INTO user_scope(user_id,role,company_id,dept_id) VALUES(#{userId},#{role},#{companyId},#{deptId})") @Options(useGeneratedKeys=true,keyProperty="id") int insertScope(Map<String,Object> s);
 @Update("UPDATE app_user SET failed_attempts=#{attempts},locked_until=#{until} WHERE id=#{id}") int failure(@Param("id")long id,@Param("attempts")int attempts,@Param("until")java.time.LocalDateTime until);
 @Update("UPDATE app_user SET password_hash=#{hash},must_change_password=FALSE,session_version=session_version+1 WHERE id=#{id}") int password(@Param("id")long id,@Param("hash")String hash);
 @Update("UPDATE app_user SET name=#{name},enabled=#{enabled},session_version=session_version+1 WHERE id=#{id}") int adminUser(@Param("id")long id,@Param("name")String name,@Param("enabled")boolean enabled);
 @Update("UPDATE app_user SET password_hash=#{hash},must_change_password=TRUE,session_version=session_version+1 WHERE id=#{id}") int resetPassword(@Param("id")long id,@Param("hash")String hash);
 @Update("UPDATE user_scope SET enabled=FALSE WHERE user_id=#{uid}") int revokeScopes(long uid);
 @Update("UPDATE app_user SET enabled=#{enabled},session_version=session_version+1 WHERE id=#{id}") int enabled(@Param("id")long id,@Param("enabled")boolean enabled);
 @Update("UPDATE app_user SET totp_secret=#{secret},totp_last_step=-1 WHERE id=#{id}") int totpSecret(@Param("id")long id,@Param("secret")String secret);
 @Update("UPDATE app_user SET totp_last_step=#{step} WHERE id=#{id} AND totp_last_step < #{step}") int totpStep(@Param("id")long id,@Param("step")long step);
 @Insert("INSERT INTO recovery_code(user_id,code_hash) VALUES(#{uid},#{hash})") int addRecovery(@Param("uid")long uid,@Param("hash")String hash);
 @Select("SELECT * FROM recovery_code WHERE user_id=#{uid} AND used_at IS NULL") List<Map<String,Object>> recovery(long uid);
 @Update("UPDATE recovery_code SET used_at=CURRENT_TIMESTAMP WHERE id=#{id} AND used_at IS NULL") int consumeRecovery(long id);
 @Update("UPDATE recovery_code SET used_at=CURRENT_TIMESTAMP WHERE user_id=#{uid} AND used_at IS NULL") int revokeRecovery(long uid);
 @Select("SELECT * FROM business_record WHERE id=#{id}") Map<String,Object> record(long id);
 @Select("SELECT * FROM business_record WHERE id=#{id} FOR UPDATE") Map<String,Object> lock(long id);
 @Select("<script>SELECT * FROM business_record WHERE kind=#{kind}<if test='company != null'> AND company_id=#{company}</if><if test='dept != null'> AND dept_id=#{dept}</if> ORDER BY id DESC</script>") List<Map<String,Object>> list(@Param("kind")String kind,@Param("company")Integer company,@Param("dept")Integer dept);
 @Select("SELECT * FROM business_record WHERE task_id=#{taskId} AND kind=#{kind} ORDER BY id") List<Map<String,Object>> children(@Param("taskId")long taskId,@Param("kind")String kind);
 @Select("<script>SELECT * FROM business_record WHERE task_id=#{taskId} AND kind='PROGRESS'<if test='!home'> AND company_id=#{company}<if test='!leader'> AND (dept_id IS NULL OR dept_id=#{dept})</if></if> ORDER BY created_at DESC,id DESC LIMIT 1</script>") Map<String,Object> latestVisibleProgress(@Param("taskId")long taskId,@Param("home")boolean home,@Param("company")Integer company,@Param("leader")boolean leader,@Param("dept")Integer dept);
 @Select("<script>SELECT DISTINCT r.* FROM business_record r WHERE r.kind='TASK'<if test='company != null'> AND (r.company_id=#{company} OR EXISTS(SELECT 1 FROM business_record s WHERE s.task_id=r.id AND s.kind='SUB_TASK' AND s.company_id=#{company}<if test='dept != null'> AND s.dept_id=#{dept}</if>))</if><if test='dept != null'> AND EXISTS(SELECT 1 FROM business_record s WHERE s.task_id=r.id AND s.kind='SUB_TASK' AND s.dept_id=#{dept} AND s.company_id=#{company})</if> ORDER BY r.id DESC</script>") List<Map<String,Object>> tasks(@Param("company")Integer company,@Param("dept")Integer dept);
 @Insert("INSERT INTO business_record(kind,company_id,dept_id,task_id,owner_id,status,payload) VALUES(#{kind},#{companyId},#{deptId},#{taskId},#{ownerId},#{status},#{payload})") @Options(useGeneratedKeys=true,keyProperty="id") int insert(Map<String,Object> r);
 @Update("UPDATE business_record SET status=#{status},payload=#{payload},owner_id=#{ownerId},version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=#{id} AND version=#{version}") int update(Map<String,Object> r);
 @Insert("INSERT INTO idempotency_record(user_id,request_key,request_hash) VALUES(#{uid},#{key},#{hash})") int reserve(@Param("uid")long uid,@Param("key")String key,@Param("hash")String hash);
 @Select("SELECT * FROM idempotency_record WHERE user_id=#{uid} AND request_key=#{key}") Map<String,Object> idempotency(@Param("uid")long uid,@Param("key")String key);
 @Update("UPDATE idempotency_record SET response_json=#{response} WHERE user_id=#{uid} AND request_key=#{key}") int finishIdempotency(@Param("uid")long uid,@Param("key")String key,@Param("response")String response);
 @Select("SELECT last_hash FROM audit_chain_anchor WHERE id=1 FOR UPDATE") String lastAudit();
 @Update("UPDATE audit_chain_anchor SET last_hash=#{hash} WHERE id=1") int advanceAudit(String hash);
 @Update("UPDATE app_user SET locked_until=CASE WHEN failed_attempts+1>=5 THEN #{until} ELSE locked_until END,failed_attempts=failed_attempts+1 WHERE id=#{id}") int incrementFailure(@Param("id")long id,@Param("until")java.time.LocalDateTime until);
 @Update("UPDATE app_user SET totp_locked_until=CASE WHEN totp_failed_attempts+1>=5 THEN #{until} ELSE totp_locked_until END,totp_failed_attempts=totp_failed_attempts+1 WHERE id=#{id}") int incrementTotpFailure(@Param("id")long id,@Param("until")java.time.LocalDateTime until);
 @Update("UPDATE app_user SET totp_failed_attempts=0,totp_locked_until=NULL WHERE id=#{id}") int clearTotpFailures(long id);
 @Insert("INSERT INTO audit_event(actor_id,company_id,action,object_id,trace_id,previous_hash,event_hash,delegation_id) VALUES(#{actor},#{company},#{action},#{object},#{trace},#{previous},#{hash},#{delegation})") int audit(Map<String,Object> row);
 @Select("SELECT * FROM audit_event WHERE company_id=#{company} ORDER BY id DESC LIMIT 1000") List<Map<String,Object>> auditList(int company);
 @Insert("INSERT INTO notification_outbox(event_key,company_id,recipient_id,task_id,title) VALUES(#{key},#{company},#{recipient},#{task},#{title})") int outbox(Map<String,Object> row);
 @Select("SELECT * FROM notification_outbox WHERE status='PENDING' AND next_attempt<=CURRENT_TIMESTAMP ORDER BY id LIMIT 100 FOR UPDATE") List<Map<String,Object>> pendingOutbox();
 @Insert("INSERT INTO notification(outbox_id,user_id,company_id,task_id,title) SELECT id,recipient_id,company_id,task_id,title FROM notification_outbox WHERE id=#{id} AND NOT EXISTS(SELECT 1 FROM notification WHERE outbox_id=#{id})") int deliver(long id);
 @Update("UPDATE notification_outbox SET status='SENT',last_error=NULL WHERE id=#{id}") int sent(long id);
 @Update("UPDATE notification_outbox SET attempts=attempts+1,next_attempt=#{next},last_error='DELIVERY_FAILURE',status=CASE WHEN attempts>=9 THEN 'DEAD' ELSE 'PENDING' END WHERE id=#{id}") int retry(@Param("id")long id,@Param("next")java.time.LocalDateTime next);
 @Select("SELECT * FROM notification WHERE user_id=#{uid} AND archived=FALSE ORDER BY id DESC") List<Map<String,Object>> notifications(long uid);
 @Update("UPDATE notification SET is_read=TRUE WHERE id=#{id} AND user_id=#{uid}") int readNotification(@Param("id")long id,@Param("uid")long uid);
 @Update("UPDATE notification SET archived=TRUE WHERE id=#{id} AND user_id=#{uid} AND is_read=TRUE AND archived=FALSE") int archiveNotification(@Param("id")long id,@Param("uid")long uid);
 @Insert("INSERT INTO kpi_run_key(company_id,period,template_id,run_id) VALUES(#{company},#{period},#{template},#{run})") int runKey(Map<String,Object> row);
 @Select("SELECT run_id FROM kpi_run_key WHERE company_id=#{company} AND period=#{period} AND template_id=#{template}") Long runFor(Map<String,Object> row);
 @Insert("INSERT INTO job_execution(execution_key,status) VALUES(#{key},'RUNNING')") int startJob(String key);
 @Update("UPDATE job_execution SET status='DONE',finished_at=CURRENT_TIMESTAMP WHERE execution_key=#{key}") int finishJob(String key);

 @Insert("INSERT INTO notification_delivery(outbox_id,channel_type,channel_id,next_attempt) VALUES(#{outbox},#{type},#{channel},#{now}) ON DUPLICATE KEY UPDATE id=id") int stageDelivery(@Param("outbox")long outbox,@Param("type")String type,@Param("channel")long channel,@Param("now")java.time.LocalDateTime now);
 @Update("UPDATE notification_outbox SET status='DELIVERING' WHERE id=#{id} AND status='PENDING'") int dispatchOutbox(long id);
 @Select("SELECT id FROM notification_delivery WHERE (status='PENDING' AND next_attempt<=#{now}) OR (status='IN_FLIGHT' AND lease_until<=#{now}) ORDER BY id LIMIT 100") List<Long> dueDeliveries(java.time.LocalDateTime now);
 @Select("SELECT d.*,o.company_id,o.task_id,o.title FROM notification_delivery d JOIN notification_outbox o ON o.id=d.outbox_id WHERE d.id=#{id} FOR UPDATE") Map<String,Object> lockDelivery(long id);
 @Update("UPDATE notification_delivery SET status='IN_FLIGHT',attempts=attempts+1,lease_until=#{until},lease_token=#{token} WHERE id=#{id}") int claimDelivery(@Param("id")long id,@Param("until")java.time.LocalDateTime until,@Param("token")String token);
 @Update("UPDATE notification_delivery SET status=#{status},completed_at=CURRENT_TIMESTAMP,lease_until=NULL,lease_token=NULL,last_error=#{error} WHERE id=#{id} AND status='IN_FLIGHT' AND lease_token=#{token}") int completeDelivery(@Param("id")long id,@Param("token")String token,@Param("status")String status,@Param("error")String error);
 @Update("UPDATE notification_delivery SET status=#{status},next_attempt=#{next},lease_until=NULL,lease_token=NULL,last_error=#{error} WHERE id=#{id} AND status='IN_FLIGHT' AND lease_token=#{token}") int failDelivery(@Param("id")long id,@Param("token")String token,@Param("status")String status,@Param("next")java.time.LocalDateTime next,@Param("error")String error);
 @Update("UPDATE notification_outbox SET status=CASE WHEN EXISTS(SELECT 1 FROM notification_delivery WHERE outbox_id=#{id} AND status='DEAD') THEN 'DEAD' WHEN EXISTS(SELECT 1 FROM notification_delivery WHERE outbox_id=#{id} AND status IN ('PENDING','IN_FLIGHT')) THEN 'DELIVERING' ELSE 'SENT' END WHERE id=#{id}") int aggregateDelivery(long id);
}
